31	export function getUserAuthInfo(): UserAuthInfo {
32	  const globalConfig = readGlobalConfig();
33	  const email = globalConfig?.account?.email || null;
34	  const isLoggedIntoCloud = !!(globalConfig?.cloud?.apiKey || process.env.PROMPTFOO_API_KEY);
35	
36	  return {
37	    email,
38	    isLoggedIntoCloud,
39	    authMethod: isLoggedIntoCloud ? 'api-key' : email ? 'email' : 'none',
40	  };
41	}
