102	export function getAuthor(override?: string | null): string | null {
103	  const userEmail = getUserEmail();
104	  const envAuthor = getEnvString('PROMPTFOO_AUTHOR');
105	  if (isLoggedIntoCloud() && userEmail) {
106	    if (override && override !== userEmail) {
107	      // Don't log the full emails — the rest of the codebase treats them as PII.
108	      logger.debug('[Author] Ignoring author override because cloud identity takes precedence');
109	    }
