87	/**
88	 * Gets the caller location (filename and line number)
89	 * @returns String with file location information
90	 */
91	export function getCallerLocation(): string {
92	  try {
93	    const error = new Error('stack trace capture');
94	    const stack = error.stack?.split('\n') || [];
95	
96	    // Skip first 3 lines (Error, getCallerLocation, and the logger method)
97	    const callerLine = stack[3];
98	
99	    if (callerLine) {
100	      // Handle different stack trace formats
101	      const matchParens = callerLine.match(/at (?:.*) \((.+):(\d+):(\d+)\)/);
102	      const matchNormal = callerLine.match(/at (.+):(\d+):(\d+)/);
103	
104	      const match = matchParens || matchNormal;
105	      if (match) {
106	        // matchParens has filePath at index 1, matchNormal has it at index 1 too
107	        const filePath = match[1];
108	        const line = match[2];
109	
110	        // Get just the filename from the path
111	        const fileName = path.basename(filePath);
112	        return `[${fileName}:${line}]`;
113	      }
114	    }
115	  } catch {
116	    // Silently handle any errors in stack trace parsing
117	  }
118	
119	  return '';
120	}
