22	export async function doRedteamRun(options: RedteamRunOptions): Promise<Eval | undefined> {
23	  if (options.verbose) {
24	    setLogLevel('debug');
25	  }
26	  if (options.logCallback) {
27	    setLogCallback(options.logCallback);
28	  }
29	
30	  // Enable live verbose toggle (press 'v' to toggle debug logs)
31	  // Only works in interactive TTY mode, not in CI or web UI
32	  const verboseToggleCleanup = options.logCallback ? null : initVerboseToggle();
33	
34	  let configPath: string = options.config ?? 'promptfooconfig.yaml';
35	
36	  // If output filepath is not provided, locate the out file in the same directory as the config file:
37	  let redteamPath;
38	  if (options.output) {
39	    redteamPath = options.output;
40	  } else {
41	    const configDir = path.dirname(configPath);
42	    redteamPath = path.join(configDir, 'redteam.yaml');
43	  }
44	
45	  // Check API health before proceeding
46	  try {
47	    const healthUrl = getRemoteHealthUrl();
48	    if (healthUrl) {
49	      logger.debug(`Checking Promptfoo API health at ${healthUrl}...`);
50	      const healthResult = await checkRemoteHealth(healthUrl);
51	      if (healthResult.status !== 'OK') {
52	        throw new Error(
53	          `Unable to proceed with redteam: ${healthResult.message}\n` +
54	            'Please check your API configuration or try again later.',
55	        );
56	      }
57	      logger.debug('API health check passed');
58	    }
59	  } catch (error) {
60	    logger.warn(
61	      `API health check failed with error: ${error}.\nPlease check your API configuration or try again later.`,
62	    );
63	  }
64	
65	  if (options.liveRedteamConfig) {
66	    // Write liveRedteamConfig to a temporary file
67	    const filename = `redteam-${Date.now()}.yaml`;
68	    const tmpDir = options.loadedFromCloud ? '' : os.tmpdir();
69	    const tmpFile = path.join(tmpDir, filename);
70	    await fs.mkdir(path.dirname(tmpFile), { recursive: true });
71	    await fs.writeFile(tmpFile, yaml.dump(options.liveRedteamConfig));
72	    redteamPath = tmpFile;
73	    // Do not use default config.
74	    configPath = tmpFile;
75	    logger.debug(`Using live config from ${tmpFile}`);
76	    logger.debug(`Live config: ${JSON.stringify(options.liveRedteamConfig, null, 2)}`);
77	  }
78	
79	  // Generate new test cases
80	  logger.info('Generating test cases...');
81	  const { maxConcurrency, ...passThroughOptions } = options;
82	
83	  let redteamConfig;
84	  const generationStartTime = Date.now();
85	  try {
